  'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA';

function _base64ToBytes(b64) {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  return bytes;
}

const BYTES_PER_ROW = Math.ceil(GRID_W / 8);
const _packed = _base64ToBytes(MASK_B64);

export function isOpenTile(gx, gy) {
  if (gx < 0 || gx >= GRID_W || gy < 0 || gy >= GRID_H) return false;
  const byteIndex = gy * BYTES_PER_ROW + (gx >> 3);
  const bitIndex = 7 - (gx & 7);
  return ((_packed[byteIndex] >> bitIndex) & 1) === 1;
}

// ── Rarity spawn zones ───────────────────────────────────────────────────────
// Which mob rarity may spawn on each walkable tile. Painted by hand as a
// colour-coded image (one colour per rarity, same palette as RARITY_TEXT in
// constants.js) and layered ON TOP of the wall mask above — this data never
// changes which tiles are walls or walkable, it only tags them.
//
// Format: one tier byte (0 = Common ... 13 = Voidbound) per tile,
// row-major, GRID_W x GRID_H, stored as run-length pairs of
// [tier byte][run length as a little-endian base-128 varint], base64-encoded.
// Wall tiles are stored as 0 and are never read (callers check canMoveTo /
// isOpenTile first).
//
// A few walkable tiles were left unpainted in the source image (thin seams
// where the walls were edited after the zones were drawn, plus small enclosed
// pockets); each of those takes the tier of its nearest painted walkable
// tile so every walkable tile has a valid tier.
